class Solution {
public:
    vector<int> maxScoreIndices(vector<int>& nums) {
        int n = nums.size();
        int totalOnes = 0;
        for (int x : nums) totalOnes += x;

        int zerosLeft = 0, onesLeft = 0;
        int best = -1;
        vector<int> result;
        for (int i = 0; i <= n; i++) {
            int score = zerosLeft + (totalOnes - onesLeft);
            if (score > best) {
                best = score;
                result.clear();
                result.push_back(i);
            } else if (score == best) {
                result.push_back(i);
            }
            if (i < n) {
                if (nums[i] == 0) zerosLeft++;
                else onesLeft++;
            }
        }
        return result;
    }
};
